-- Two industries the library had nothing for: Real Estate, and construction
-- as a trade in its own right.
--
-- 20260820000000 filled the gap for electricians, HVAC techs and plumbers, and
-- the reasoning here is the same one step further out. An agent doing a
-- move-out inspection, a property manager writing a condition report, a GC
-- walking a punch list or putting together a draw request all opened "More
-- Templates" and found a generic site report. So they used a generic site
-- report, and the document they handed over said less than it should have.
--
-- Six templates, three per industry, each shaped like the paperwork that
-- industry already produces:
--
--   Real Estate   - the tenancy inspection, the condition report, the listing
--                   sheet. Two are evidence documents and one is marketing,
--                   which is genuinely the split of what an agent writes.
--   Construction  - before (pre-construction survey), during (draw request)
--                   and the end (punch list). "Daily Site Report" already
--                   exists under Field Reports and is deliberately not
--                   duplicated here.
--
-- Both category strings are new, so apps/web/src/lib/template-categories.ts
-- gains 'Construction' and 'Real Estate' in the same change. The picker and the
-- Templates page both rank headings from that list, and
-- tests/document-template-library.test.ts fails a seeded category that is not
-- in it. They are also what packages/shared/src/industries.ts points the
-- construction and real_estate industries at, which is how answering the setup
-- wizard puts these at the top of the library rather than seventh.
--
-- Ownerless built-ins (team_id IS NULL AND created_by IS NULL), so the read
-- policy from 20260803000000 already covers them and nobody can edit one in
-- place. "Duplicate to edit" is the way in, same as the rest of the library.
--
-- Every body is written with [bracketed] blanks rather than filler prose, per
-- 20260824000000: the blanks become click-to-type fields, and prose becomes
-- something the tech has to select and delete before typing.
--
-- Requires 20260803000000 (nullable created_by, unique slug index). No schema
-- change of its own, so this takes row locks only.
--
-- Idempotent - ON CONFLICT (slug) DO UPDATE. Safe to re-run.
-- Apply manually in the Supabase SQL editor (or `supabase db push`).

INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-realestate-move-in-out-inspection',
  NULL,
  NULL,
  'Move-In & Move-Out Inspection',
  jsonb_build_object(
    'style', 'report',
    'category', 'Real Estate',
    'description', 'Room-by-room condition record for a tenancy: meter readings, keys handed over, photographed damage and a signed comparison the deposit can be settled against.',
    'html', $html$<h1>Move-In and Move-Out Inspection</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><p><em><span style="color: rgb(140,148,162)">Same form both ends of the tenancy. Photograph every room even where nothing is wrong, because that is the photo you will want later.</span></em></p><h2>Tenancy</h2><table><tbody><tr><th><p>Inspection type</p></th><th><p>Tenant</p></th><th><p>Contact</p></th><th><p>Reference</p></th><th><p>Date</p></th></tr><tr><td><p>[Move-in or move-out]</p></td><td><p>{{client_name}}</p></td><td><p>{{client_contact}}</p></td><td><p>{{project_number}}</p></td><td><p>{{date}}</p></td></tr></tbody></table><h2>Utilities and keys</h2><table><tbody><tr><th><p>Item</p></th><th><p>Reading or count</p></th><th><p>Notes</p></th></tr><tr><td><p>Electricity meter</p></td><td><p>[Reading]</p></td><td><p>[Meter serial]</p></td></tr><tr><td><p>Gas meter</p></td><td><p>[Reading]</p></td><td><p>[Meter serial]</p></td></tr><tr><td><p>Water meter</p></td><td><p>[Reading]</p></td><td><p>[Meter serial]</p></td></tr><tr><td><p>Keys and fobs handed over</p></td><td><p>[How many]</p></td><td><p>[Which doors]</p></td></tr><tr><td><p>Alarm or entry code given</p></td><td><p>[Yes or no]</p></td><td><p>[Who holds it]</p></td></tr></tbody></table><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EMeter%20board%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Meter board"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EKeys%20handed%20over%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Keys handed over"></p><h2>Condition by room</h2><p><em><span style="color: rgb(140,148,162)">Grade each room good, fair, worn or damaged, then photograph anything below good.</span></em></p><table><tbody><tr><th><p>Room</p></th><th><p>Walls and ceiling</p></th><th><p>Floor</p></th><th><p>Fixtures</p></th><th><p>Grade</p></th><th><p>Notes</p></th></tr><tr><td><p>Entrance and hall</p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Living room</p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Kitchen</p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Bedroom 1</p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Bedroom 2</p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Bathroom</p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Other</p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EKitchen%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Kitchen"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EBathroom%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Bathroom"></p><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3ELiving%20room%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Living room"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EBedroom%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Bedroom"></p><h2>Appliances and systems</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Boiler or furnace fires and holds temperature</p></li><li data-type="taskItem" data-checked="false"><p>Smoke and carbon monoxide alarms tested</p></li><li data-type="taskItem" data-checked="false"><p>Every window opens, closes and locks</p></li><li data-type="taskItem" data-checked="false"><p>Taps run and drains clear</p></li><li data-type="taskItem" data-checked="false"><p>Oven, hob and extractor working</p></li><li data-type="taskItem" data-checked="false"><p>Fridge, washer and dryer working</p></li><li data-type="taskItem" data-checked="false"><p>No damp, mould or water staining found</p></li><li data-type="taskItem" data-checked="false"><p>Property left clean to the standard agreed</p></li></ul><h2>Damage and deductions</h2><p><em><span style="color: rgb(140,148,162)">Move-out only. Fair wear and tear is not damage, so say which this is.</span></em></p><table><tbody><tr><th><p>Room</p></th><th><p>What is damaged</p></th><th><p>Wear or damage</p></th><th><p>Estimated cost</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EDamage%201%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Damage 1"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EDamage%202%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Damage 2"></p><h2>Tenant comments</h2><p>[Anything the tenant disagrees with]</p><h2>Overall</h2><p>[Condition of the property as a whole]</p><h2>Sign-off</h2><table><tbody><tr><th><p></p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p><strong>Inspector</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Tenant</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Landlord or agent</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><hr><p><span style="color: rgb(156,163,175)">{{company}} &nbsp;·&nbsp; {{company_address}} &nbsp;·&nbsp; {{company_phone}}</span></p>$html$
  ),
  ARRAY['client_name', 'client_contact', 'company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name', 'project_number']
)
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
    body = EXCLUDED.body,
    fields = EXCLUDED.fields,
    archived = false;
INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'sitepix-realestate-property-condition-report',
  NULL,
  NULL,
  'Property Condition Report',
  jsonb_build_object(
    'style', 'report',
    'category', 'Real Estate',
    'description', 'Whole-property survey for an owner, buyer or lender: exterior, interior, services and roof, with a prioritised defect list and photographs to back each one.',
    'html', $html$<h1>Property Condition Report</h1><p><strong>{{project_name}}</strong> &nbsp;·&nbsp; {{project_address}}</p><p><span style="color: rgb(120,128,142)">{{date}} &nbsp;·&nbsp; Prepared by {{prepared_by}} &nbsp;·&nbsp; {{company}}</span></p><hr><p><strong>Prepared for:</strong> {{client_name}} &nbsp;·&nbsp; <strong>Reference:</strong> {{project_number}} &nbsp;·&nbsp; <strong>Conditions:</strong> {{weather}}</p><hr><p><em><span style="color: rgb(140,148,162)">Walk the outside first, then the roof, then room by room inside.</span></em></p><h2>1. Property details</h2><table><tbody><tr><th><p>Property type</p></th><th><p>Approx. year built</p></th><th><p>Floors</p></th><th><p>Bedrooms</p></th><th><p>Occupied</p></th></tr><tr><td><p>[House, flat, unit]</p></td><td><p>[Year]</p></td><td><p>[How many]</p></td><td><p>[How many]</p></td><td><p>[Yes or no]</p></td></tr></tbody></table><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'720'%20height%3D'300'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'719'%20height%3D'299'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'360'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EFront%20elevation%3C%2Ftext%3E%3Ctext%20x%3D'360'%20y%3D'164'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="100%" height="300" alt="Front elevation"></p><h2>2. Exterior</h2><table><tbody><tr><th><p>Element</p></th><th><p>Condition</p></th><th><p>Observation</p></th><th><p>Action</p></th></tr><tr><td><p>Roof covering</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Gutters and downpipes</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Walls and render</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Windows and doors</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Drainage and grading</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Driveway, paths, fencing</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3ERoof%20and%20gutters%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Roof and gutters"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EExterior%20defect%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Exterior defect"></p><h2>3. Interior</h2><table><tbody><tr><th><p>Room or area</p></th><th><p>Condition</p></th><th><p>Observation</p></th><th><p>Action</p></th></tr><tr><td><p>Entrance and hall</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Living areas</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Kitchen</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Bedrooms</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Bathrooms</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Basement, loft, garage</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EInterior%201%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Interior 1"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EInterior%202%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Interior 2"></p><h2>4. Services</h2><table><tbody><tr><th><p>System</p></th><th><p>Age or rating</p></th><th><p>Condition</p></th><th><p>Observation</p></th></tr><tr><td><p>Heating</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Hot water</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Electrical</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Plumbing and drainage</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p>Ventilation</p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><h2>5. Safety checks</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Smoke alarms present on every floor and tested</p></li><li data-type="taskItem" data-checked="false"><p>Carbon monoxide alarm near every fuel appliance</p></li><li data-type="taskItem" data-checked="false"><p>Handrails and balustrades secure</p></li><li data-type="taskItem" data-checked="false"><p>No exposed wiring or damaged sockets</p></li><li data-type="taskItem" data-checked="false"><p>Escape routes and external doors clear</p></li><li data-type="taskItem" data-checked="false"><p>No visible damp, mould or active leak</p></li></ul><h2>6. Defects, by priority</h2><table><tbody><tr><th><p>Priority</p></th><th><p>Defect</p></th><th><p>Where</p></th><th><p>Risk if left</p></th><th><p>Recommended fix</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EDefect%201%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Defect 1"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'240'%20height%3D'260'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'239'%20height%3D'259'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'120'%20y%3D'124'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EDefect%202%3C%2Ftext%3E%3Ctext%20x%3D'120'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="260" alt="Defect 2"></p><h2>7. Summary and recommendation</h2><p>[Overall condition, in one paragraph]</p><p>[What should be dealt with first, and why]</p><h2>8. Limitations</h2><p>[What was not inspected, and why not]</p><h2>Sign-off</h2><table><tbody><tr><th><p></p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p><strong>Inspector</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p><strong>Client</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><hr><p><span style="color: rgb(156,163,175)">{{company}} &nbsp;·&nbsp; {{company_address}} &nbsp;·&nbsp; {{company_phone}}</span></p>$html$
  ),
  ARRAY['client_name', 'company', 'company_address', 'company_phone', 'date', 'prepared_by', 'project_address', 'project_name', 'project_number', 'weather']
)
