  'Listing Photo & Feature Sheet',
  jsonb_build_object(
    'style', 'report',
    'category', 'Real Estate',
    'description', 'Client-facing sheet for a property going to market: headline facts, room-by-room photographs with captions, selling points and the viewing arrangements.',
    'html', $html$<h1>{{project_name}}</h1><p><strong>{{project_address}}</strong></p><p><span style="color: rgb(120,128,142)">Listed by {{prepared_by}}, {{prepared_by_title}} &nbsp;·&nbsp; {{company}} &nbsp;·&nbsp; {{date}}</span></p><hr><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'720'%20height%3D'300'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'719'%20height%3D'299'%20rx%3D'8'%20fill%3D'rgb(246%2C247%2C249)'%20stroke%3D'rgb(199%2C205%2C214)'%20stroke-dasharray%3D'6%205'%2F%3E%3Ctext%20x%3D'360'%20y%3D'144'%20font-family%3D'sans-serif'%20font-size%3D'13'%20font-weight%3D'700'%20fill%3D'rgb(100%2C108%2C124)'%20text-anchor%3D'middle'%3EHero%20shot%20-%20front%20of%20property%3C%2Ftext%3E%3Ctext%20x%3D'360'%20y%3D'164'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(150%2C158%2C172)'%20text-anchor%3D'middle'%3ETap%20to%20add%20photo%3C%2Ftext%3E%3C%2Fsvg%3E" width="100%" height="300" alt="Hero shot - front of property"></p><h2>At a glance</h2><table><tbody><tr><th><p>Asking price</p></th><th><p>Bedrooms</p></th><th><p>Bathrooms</p></th><th><p>Floor area</p></th><th><p>Lot size</p></th><th><p>Year built</p></th></tr><tr><td><p>[Price]</p></td><td><p>[How many]</p></td><td><p>[How many]</p></td><td><p>[Area]</p></td><td><p>[Size]</p></td><td><p>[Year]</p></td></tr></tbody></table><table><tbody><tr><th><p>Property type</p></th><th><p>Parking</p></th><th><p>Heating</p></th><th><p>Outside space</p></th><th><p>Available from</p></th></tr><tr><td><p>[Type]</p></td><td><p>[Spaces]</p></td><td><p>[Type]</p></td><td><p>[Garden, balcony, none]</p></td><td><p>[Date]</p></td></tr></tbody></table><h2>The property</h2><p><em><span style="color: rgb(140,148,162)">Two or three sentences. Say what someone would notice walking in.</span></em></p><p>[Describe the property]</p><h2>Room by room</h2><h3>Living space</h3><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20wid